// Hand-rolled Zod-style validator. Collects ALL violations, never lets a
// malformed scenario reach the database or the LLM.
const cfg = $input.first().json;
const body = cfg.body || {};
const errors = [];
const add = (field, message) => errors.push({ field, message });
const isStr = v => typeof v === 'string' && v.trim().length > 0;
const isNum = v => typeof v === 'number' && Number.isFinite(v);
const nu = u => String(u || '').trim().replace(/[#?].*$/, '').replace(/\/+$/, '') || '/';

if (!isStr(body.siteId)) add('siteId', 'siteId is required and must be a non-empty string');
if (!isStr(body.tenantId)) add('tenantId', 'tenantId is required and must be a non-empty string');
if (body.scenarioName !== undefined && (typeof body.scenarioName !== 'string' || body.scenarioName.length > 120)) add('scenarioName', 'scenarioName must be a string of at most 120 characters');

let horizonMonths = cfg.defaultHorizonMonths;
if (body.horizonMonths !== undefined) {
  if (!Number.isInteger(body.horizonMonths) || body.horizonMonths < 1 || body.horizonMonths > cfg.maxHorizonMonths) {
    add('horizonMonths', `horizonMonths must be an integer between 1 and ${cfg.maxHorizonMonths}`);
  } else horizonMonths = body.horizonMonths;
}

const actions = [];
const consumed = new Map();   // url -> action index that merges it away / removes it
const targets = [];           // merge targets, checked against consumed[] after the loop

if (!Array.isArray(body.actions) || body.actions.length === 0) {
  add('actions', 'actions must be a non-empty array');
} else if (body.actions.length > cfg.maxActions) {
  add('actions', `actions cannot contain more than ${cfg.maxActions} items`);
} else {
  body.actions.forEach((a, i) => {
    const p = `actions[${i}]`;
    if (!a || typeof a !== 'object') { add(p, 'must be an object'); return; }

    if (a.type === 'merge') {
      const okTarget = isStr(a.targetUrl);
      const okSources = Array.isArray(a.sourceUrls) && a.sourceUrls.length > 0 && a.sourceUrls.every(isStr);
      if (!okTarget) add(`${p}.targetUrl`, 'targetUrl is required');
      if (!okSources) add(`${p}.sourceUrls`, 'sourceUrls must be a non-empty array of URLs');
      if (a.redirect !== undefined && typeof a.redirect !== 'boolean') add(`${p}.redirect`, 'redirect must be a boolean');
      if (okTarget && okSources) {
        const target = nu(a.targetUrl);
        const sources = [...new Set(a.sourceUrls.map(nu))];
        if (sources.includes(target)) add(`${p}.sourceUrls`, 'target cannot also be a source');
        sources.forEach(s => {
          if (consumed.has(s)) add(`${p}.sourceUrls`, `${s} is already used by actions[${consumed.get(s)}]`);
          else consumed.set(s, i);
        });
        targets.push({ url: target, i });
        actions.push({ index: i, type: 'merge', targetUrl: target, sourceUrls: sources, redirect: a.redirect !== false });
      }
    } else if (a.type === 'new') {
      let ok = true;
      if (!isStr(a.targetKeyword)) { add(`${p}.targetKeyword`, 'targetKeyword is required'); ok = false; }
      if (!isNum(a.searchVolume) || a.searchVolume < 0) { add(`${p}.searchVolume`, 'searchVolume must be a number >= 0 (monthly searches)'); ok = false; }
      if (!isNum(a.keywordDifficulty) || a.keywordDifficulty < 0 || a.keywordDifficulty > 100) { add(`${p}.keywordDifficulty`, 'keywordDifficulty must be a number between 0 and 100'); ok = false; }
      if (a.contentQuality !== undefined && (!isNum(a.contentQuality) || a.contentQuality < 0 || a.contentQuality > 1)) { add(`${p}.contentQuality`, 'contentQuality must be between 0 and 1'); ok = false; }
      if (a.clusterId !== undefined && typeof a.clusterId !== 'string') { add(`${p}.clusterId`, 'clusterId must be a string'); ok = false; }
      if (ok) actions.push({
        index: i, type: 'new',
        title: isStr(a.title) ? a.title.trim() : null,
        targetKeyword: a.targetKeyword.toLowerCase().trim(),
        searchVolume: a.searchVolume,
        keywordDifficulty: a.keywordDifficulty,
        contentQuality: a.contentQuality === undefined ? 0.7 : a.contentQuality,
        clusterId: a.clusterId || null
      });
    } else if (a.type === 'remove') {
      const strategy = a.strategy === undefined ? 'redirect' : a.strategy;
      let ok = true;
      if (!isStr(a.url)) { add(`${p}.url`, 'url is required'); ok = false; }
      if (!['redirect', '410', 'noindex'].includes(strategy)) { add(`${p}.strategy`, "strategy must be one of: redirect, 410, noindex"); ok = false; }
      if (strategy === 'redirect' && !isStr(a.redirectTo)) { add(`${p}.redirectTo`, 'redirectTo is required when strategy is redirect'); ok = false; }
      if (ok) {
        const url = nu(a.url);
        if (consumed.has(url)) add(`${p}.url`, `${url} is already used by actions[${consumed.get(url)}]`);
        else consumed.set(url, i);
        actions.push({ index: i, type: 'remove', url, strategy, redirectTo: strategy === 'redirect' ? nu(a.redirectTo) : null });
      }
    } else {
      add(`${p}.type`, "type must be one of: merge, new, remove");
    }
  });
  targets.forEach(t => {
    if (consumed.has(t.url)) add(`actions[${t.i}].targetUrl`, `${t.url} is merged away or removed by actions[${consumed.get(t.url)}]`);
  });
}

return [{
  json: {
    isValid: errors.length === 0,
    validationErrors: errors,
    siteId: isStr(body.siteId) ? body.siteId.trim() : null,
    tenantId: isStr(body.tenantId) ? body.tenantId.trim() : null,
    scenarioName: isStr(body.scenarioName) ? body.scenarioName.trim() : 'Untitled scenario',
    horizonMonths,
    actions,
    serpFeatureFactor: cfg.serpFeatureFactor,
    requestStartedAt: new Date().toISOString()
  }
}];

// Turns raw Search Console / crawl rows into a baseline model of the CURRENT site.
const ctx = $('Code - Validate Request Schema').first().json;
const rows = $input.all().map(i => i.json).filter(r => r && r.url);

const nu = u => String(u || '').trim().replace(/[#?].*$/, '').replace(/\/+$/, '') || '/';
const num = v => { const n = Number(v); return Number.isFinite(n) ? n : 0; };

// Approximate organic CTR by average position (industry-style curve; tune per site).
const ctrCurve = [[1,0.285],[2,0.157],[3,0.11],[4,0.08],[5,0.062],[6,0.048],[7,0.038],[8,0.031],[9,0.026],[10,0.022],[15,0.011],[20,0.006],[30,0.002],[50,0.0005]];
function ctrAt(pos) {
  if (pos <= ctrCurve[0][0]) return ctrCurve[0][1];
  for (let i = 1; i < ctrCurve.length; i++) {
    if (pos <= ctrCurve[i][0]) {
      const [x0, y0] = ctrCurve[i - 1], [x1, y1] = ctrCurve[i];
      return y0 + (y1 - y0) * (pos - x0) / (x1 - x0);
    }
  }
  return ctrCurve[ctrCurve.length - 1][1];
}

const pages = rows.map(r => ({
  url: nu(r.url),
  clicks: num(r.clicks),
  impressions: num(r.impressions),
  position: num(r.avg_position) || 50,
  backlinks: num(r.backlinks),
  wordCount: num(r.word_count),
  clusterId: r.cluster_id ? String(r.cluster_id) : null,
  primaryKeyword: r.primary_keyword ? String(r.primary_keyword).toLowerCase().trim() : null,
  internalLinksIn: num(r.internal_links_in)
}));

const totalClicks = pages.reduce((t, p) => t + p.clicks, 0);
const totalImpr = pages.reduce((t, p) => t + p.impressions, 0);
const totalBacklinks = pages.reduce((t, p) => t + p.backlinks, 0);
const avgPosition = totalImpr > 0
  ? pages.reduce((t, p) => t + p.position * p.impressions, 0) / totalImpr
  : (pages.length ? pages.reduce((t, p) => t + p.position, 0) / pages.length : 0);

// How far real CTR deviates from the generic curve, site-wide (clamped).
const modelled = pages.reduce((t, p) => t + p.impressions * ctrAt(p.position), 0);
const ctrCalibration = modelled > 0 ? Math.min(1.5, Math.max(0.5, totalClicks / modelled)) : 1;

const clusters = {};
pages.forEach(p => {
  if (!p.clusterId) return;
  clusters[p.clusterId] = clusters[p.clusterId] || { clicks: 0, pages: 0 };
  clusters[p.clusterId].clicks += p.clicks;
  clusters[p.clusterId].pages += 1;
});

// Existing keyword cannibalization (2+ pages targeting the same primary keyword).
const kwGroups = {};
pages.forEach(p => { if (p.primaryKeyword) (kwGroups[p.primaryKeyword] = kwGroups[p.primaryKeyword] || []).push(p.url); });
const cannibalization = Object.entries(kwGroups).filter(([, urls]) => urls.length > 1).map(([keyword, urls]) => ({ keyword, urls }));

return [{
  json: {
    siteId: ctx.siteId,
    tenantId: ctx.tenantId,
    scenarioName: ctx.scenarioName,
    horizonMonths: ctx.horizonMonths,
    actions: ctx.actions,
    serpFeatureFactor: ctx.serpFeatureFactor,
    requestStartedAt: ctx.requestStartedAt,
    noData: pages.length === 0,
    pages,
    totals: {
      pages: pages.length,
      clicks: totalClicks,
      impressions: totalImpr,
      backlinks: totalBacklinks,
      avgPosition: Math.round(avgPosition * 100) / 100,
      ctrCalibration
    },
    siteAuthority: Math.min(1, Math.log10(1 + totalBacklinks) / 4),
    clusters,
    cannibalization,
    ctrCurve
  }
}];

// SIMULATION BRANCH 1 — Merge Pages (consolidate N pages into a target, usually via 301).
const b = $input.first().json;
function ctrAt(pos) {
  const c = b.ctrCurve;
  if (pos <= c[0][0]) return c[0][1];
  for (let i = 1; i < c.length; i++) {
    if (pos <= c[i][0]) { const [x0, y0] = c[i - 1], [x1, y1] = c[i]; return y0 + (y1 - y0) * (pos - x0) / (x1 - x0); }
  }
  return c[c.length - 1][1];
}
const byUrl = new Map(b.pages.map(p => [p.url, p]));
const results = [], warnings = [];

for (const a of b.actions.filter(x => x.type === 'merge')) {
  const target = byUrl.get(a.targetUrl);
  if (!target) { warnings.push(`actions[${a.index}]: merge target ${a.targetUrl} not found in the latest SEO snapshot; skipped`); continue; }
  const sources = [];
  for (const u of a.sourceUrls) {
    const p = byUrl.get(u);
    if (p) sources.push(p); else warnings.push(`actions[${a.index}]: source ${u} not found in the latest SEO snapshot; ignored`);
  }
  if (!sources.length) { warnings.push(`actions[${a.index}]: no valid source pages; skipped`); continue; }

  const group = [target, ...sources];
  const baselineClicks = group.reduce((t, p) => t + p.clicks, 0);

  // Page-level CTR calibration so "no-op" merges produce ~0 delta.
  const rawTarget = target.impressions * ctrAt(target.position);
  const calib = rawTarget > 0 && target.clicks > 0 ? Math.min(3, Math.max(0.3, target.clicks / rawTarget)) : b.totals.ctrCalibration;

  // Impressions that are genuinely NEW to the merged page (same-keyword pages mostly overlap).
  let sameKw = 0, sameCluster = 0, cross = 0, addedImpr = 0;
  for (const s of sources) {
    const kw = target.primaryKeyword && s.primaryKeyword === target.primaryKeyword;
    const cl = target.clusterId && s.clusterId === target.clusterId;
    addedImpr += s.impressions * (kw ? 0.15 : cl ? 0.5 : 0.85);
    if (kw) sameKw++; else if (cl) sameCluster++; else cross++;
  }
  const retention = a.redirect ? 0.9 : 0.5;
  const mergedImpr = target.impressions + addedImpr * retention;

  // Link-equity consolidation + de-cannibalization -> position gain (capped).
  const bestPos = Math.min(...group.map(p => p.position));
  const mergedBacklinks = target.backlinks + sources.reduce((t, s) => t + s.backlinks, 0) * (a.redirect ? 0.9 : 0.3);
  const equityGain = Math.log10(1 + mergedBacklinks) - Math.log10(1 + target.backlinks);
  const boost = Math.min(2.5, equityGain * 1.5 + Math.min(sameKw, 2) * 0.8 + sameCluster * 0.2);
  const newPos = Math.max(1, bestPos - boost);

  const structural = mergedImpr * ctrAt(bestPos) * calib;   // immediate effect (redirects settle)
  const finalClicks = mergedImpr * ctrAt(newPos) * calib;   // after consolidation gains

  const flags = [];
  if (!a.redirect) flags.push('MERGE_NO_REDIRECT');
  if (cross > 0) flags.push('MERGE_CROSS_CLUSTER');
  if (target.clicks < Math.max(...sources.map(s => s.clicks))) flags.push('MERGE_TARGET_WEAKER');
  if (sources.length > 4) flags.push('MERGE_LARGE');

  results.push({
    actionIndex: a.index, type: 'merge',
    label: `Merge ${sources.length} page(s) into ${target.url}`,
    baselineClicks,
    immediateDelta: structural - baselineClicks,
    rampedDelta: finalClicks - structural,
    rampMonths: 3, lagMonths: 0, uncertainty: 0.35,
    flags,
    details: { sameKeywordSources: sameKw, sameClusterSources: sameCluster, crossClusterSources: cross,
               positionBefore: Math.round(bestPos * 10) / 10, positionAfter: Math.round(newPos * 10) / 10 }
  });
}
return [{ json: { branch: 'merge', results, warnings } }];

// SIMULATION BRANCH 2 — New Pages (expected steady-state ranking x search demand).
const b = $input.first().json;
function ctrAt(pos) {
  const c = b.ctrCurve;
  if (pos <= c[0][0]) return c[0][1];
  for (let i = 1; i < c.length; i++) {
    if (pos <= c[i][0]) { const [x0, y0] = c[i - 1], [x1, y1] = c[i]; return y0 + (y1 - y0) * (pos - x0) / (x1 - x0); }
  }
  return c[c.length - 1][1];
}
const results = [], warnings = [];

for (const a of b.actions.filter(x => x.type === 'new')) {
  const clusterClicks = a.clusterId && b.clusters[a.clusterId] ? b.clusters[a.clusterId].clicks : 0;
  const flags = [];

  // Expected position: harder keyword = worse; more site authority / better content / topical cluster = better.
  let pos = 4 + a.keywordDifficulty * 0.18
              - b.siteAuthority * 4
              - (a.contentQuality - 0.5) * 4
              + (clusterClicks > 0 ? -1.5 : 2);
  pos = Math.min(50, Math.max(1, pos));
  if (clusterClicks === 0) flags.push('NEW_TOPIC_NO_CLUSTER_AUTHORITY');
  if (pos > 15) flags.push('NEW_LOW_RANKING_ODDS');

  const rawClicks = a.searchVolume * ctrAt(pos) * b.serpFeatureFactor * b.totals.ctrCalibration;

  // If an existing page already targets this keyword, the new page mostly splits the demand.
  const existing = b.pages.filter(p => p.primaryKeyword === a.targetKeyword);
  let incremental = rawClicks;
  if (existing.length) { incremental = rawClicks * 0.4; flags.push('NEW_CANNIBALIZES_EXISTING'); }

  results.push({
    actionIndex: a.index, type: 'new',
    label: `New page: "${a.title || a.targetKeyword}"`,
    baselineClicks: 0,
    immediateDelta: 0,
    rampedDelta: incremental,
    rampMonths: 6, lagMonths: 1, uncertainty: 0.6,
    flags,
    details: { expectedPosition: Math.round(pos * 10) / 10, existingPagesSameKeyword: existing.map(p => p.url) }
  });
}
return [{ json: { branch: 'new', results, warnings } }];

// SIMULATION BRANCH 3 — Remove Pages (redirect / 410 / noindex).
const b = $input.first().json;
const byUrl = new Map(b.pages.map(p => [p.url, p]));
const results = [], warnings = [];
let thinCount = 0;

for (const a of b.actions.filter(x => x.type === 'remove')) {
  const page = byUrl.get(a.url);
  if (!page) { warnings.push(`actions[${a.index}]: ${a.url} not found in the latest SEO snapshot; skipped`); continue; }
  const flags = [];

  // How much of the lost traffic comes back via a redirect to a related page.
  let rate = 0;
  if (a.strategy === 'redirect') {
    const dest = byUrl.get(a.redirectTo);
    if (!dest) { flags.push('REMOVE_REDIRECT_TARGET_UNTRACKED'); rate = 0.3; }
    else rate = dest.clusterId && dest.clusterId === page.clusterId ? 0.6 : 0.3;
  }
  if (b.totals.clicks > 0 && page.clicks / b.totals.clicks > 0.1) flags.push('REMOVE_HIGH_TRAFFIC_PAGE');
  if (page.backlinks >= 5 && a.strategy !== 'redirect') flags.push('REMOVE_LOSES_BACKLINKS');
  if (page.internalLinksIn >= 10) flags.push('REMOVE_HIGH_INTERNAL_LINKS');
  if (page.wordCount > 0 && page.wordCount < 300 && page.clicks <= 2) thinCount++;

  results.push({
    actionIndex: a.index, type: 'remove',
    label: `Remove ${page.url} (${a.strategy})`,
    baselineClicks: page.clicks,
    immediateDelta: -page.clicks,
    rampedDelta: page.clicks * rate,
    rampMonths: 2, lagMonths: 0, uncertainty: 0.25,
    flags,
    details: { strategy: a.strategy, recoveryRate: rate }
  });
}

// Speculative site-quality signal from pruning genuinely thin, traffic-less pages.
if (thinCount > 0) {
  results.push({
    actionIndex: null, type: 'quality_signal',
    label: `Thin-content cleanup (${thinCount} page(s)) — speculative`,
    baselineClicks: 0,
    immediateDelta: 0,
    rampedDelta: Math.min(0.02, thinCount * 0.002) * b.totals.clicks,
    rampMonths: 4, lagMonths: 1, uncertainty: 0.9,
    flags: [], details: { thinPages: thinCount }
  });
}
return [{ json: { branch: 'remove', results, warnings } }];

// PREDICTED IMPACT — merge the three simulation branches into one forecast.
const b = $('Code - Build Baseline Model').first().json;
const parts = $input.all().map(i => i.json);
const results = parts.flatMap(p => p.results || []);
const warnings = parts.flatMap(p => p.warnings || []);
const H = b.horizonMonths;
const baseClicks = b.totals.clicks;

const round = (n, d = 0) => { const f = Math.pow(10, d); return Math.round(n * f) / f; };
const frac = (r, m) => Math.min(1, Math.max(0, (m - (r.lagMonths || 0)) / r.rampMonths));
const deltaAt = (r, m) => m < 1 ? 0 : r.immediateDelta + r.rampedDelta * frac(r, m);
// Independent errors combine as root-sum-of-squares.
const bandAt = m => Math.sqrt(results.reduce((t, r) => t + Math.pow(deltaAt(r, m) * r.uncertainty, 2), 0));

const timeline = [];
for (let m = 0; m <= H; m++) {
  const d = results.reduce((t, r) => t + deltaAt(r, m), 0);
  const band = bandAt(m);
  timeline.push({
    month: m,
    expected: round(Math.max(0, baseClicks + d)),
    low: round(Math.max(0, baseClicks + d - band)),
    high: round(Math.max(0, baseClicks + d + band))
  });
}
const end = timeline[timeline.length - 1];
const delta = end.expected - baseClicks;
const deltaLow = end.low - baseClicks;
const deltaHigh = end.high - baseClicks;

// Risk scoring
const W = {
  REMOVE_HIGH_TRAFFIC_PAGE: 15, REMOVE_LOSES_BACKLINKS: 15, MERGE_NO_REDIRECT: 15,
  REMOVE_HIGH_INTERNAL_LINKS: 8, MERGE_CROSS_CLUSTER: 8, MERGE_TARGET_WEAKER: 8, NEW_LOW_RANKING_ODDS: 8, REMOVE_REDIRECT_TARGET_UNTRACKED: 8,
  MERGE_LARGE: 3, NEW_CANNIBALIZES_EXISTING: 3, NEW_TOPIC_NO_CLUSTER_AUTHORITY: 3
};
const flags = [];
results.forEach(r => (r.flags || []).forEach(code => flags.push({ code, actionIndex: r.actionIndex, weight: W[code] !== undefined ? W[code] : 5 })));
const touched = results.filter(r => r.type === 'merge' || r.type === 'remove').reduce((t, r) => t + r.baselineClicks, 0);
const touchedShare = baseClicks > 0 ? Math.min(1, touched / baseClicks) : 0;
const riskScore = Math.min(100, Math.round(flags.reduce((t, f) => t + f.weight, 0) + touchedShare * 50));
const riskLevel = riskScore < 25 ? 'low' : riskScore < 50 ? 'medium' : 'high';

// Verdict
let verdict;
if (results.length === 0) verdict = 'no_valid_actions';
else if (deltaLow > 0) verdict = 'positive';
else if (deltaHigh < 0) verdict = 'negative';
else verdict = delta >= 0 ? 'leans_positive' : 'leans_negative';

// Confidence: penalise skipped actions, long horizons, and reliance on new-page forecasts.
const absTotal = results.reduce((t, r) => t + Math.abs(deltaAt(r, H)), 0);
const absNew = results.filter(r => r.type === 'new').reduce((t, r) => t + Math.abs(deltaAt(r, H)), 0);
const newShare = absTotal > 0 ? absNew / absTotal : 0;
const confidencePercent = Math.max(20, 85 - Math.min(30, warnings.length * 5) - (H > 9 ? 10 : 0) - Math.round(newShare * 25));

const actionRows = results.map(r => {
  const d = deltaAt(r, H);
  return {
    actionIndex: r.actionIndex, type: r.type, label: r.label,
    baselineClicks: round(r.baselineClicks),
    expectedDelta: round(d), low: round(d - Math.abs(d) * r.uncertainty), high: round(d + Math.abs(d) * r.uncertainty),
    flags: r.flags, details: r.details
  };
}).sort((x, y) => Math.abs(y.expectedDelta) - Math.abs(x.expectedDelta));

const byType = t => {
  const rs = results.filter(r => r.type === t);
  return { count: rs.length, expectedDelta: round(rs.reduce((s, r) => s + deltaAt(r, H), 0)) };
};

const responsePayload = {
  scenarioName: b.scenarioName,
  siteId: b.siteId,
  horizonMonths: H,
  methodology: 'heuristic-v1',
  baseline: { clicks: round(baseClicks), impressions: round(b.totals.impressions), pages: b.totals.pages, avgPosition: b.totals.avgPosition },
  predicted: {
    clicks: end.expected, low: end.low, high: end.high,
    deltaClicks: round(delta),
    deltaPercent: baseClicks > 0 ? round(delta / baseClicks * 100, 1) : null,
    deltaLow: round(deltaLow), deltaHigh: round(deltaHigh)
  },
  breakdown: { merge: byType('merge'), new: byType('new'), remove: byType('remove'), quality_signal: byType('quality_signal') },
  verdict,
  risk: { score: riskScore, level: riskLevel, flags: flags.map(f => ({ code: f.code, actionIndex: f.actionIndex })) },
  confidencePercent,
  actions: actionRows,
  timeline,
  existingCannibalization: b.cannibalization.slice(0, 20),
  warnings,
  assumptions: [
    'Clicks are modelled from impressions x a position-based CTR curve, calibrated to the site\'s own CTR.',
    'Merges assume 301 redirects retain ~90% of unique impressions and consolidate link equity (capped ~2.5 position gain).',
    'New-page traffic depends on keyword difficulty, site authority, topical cluster strength and content quality; treated as highest uncertainty.',
    'Removals lose the page\'s clicks immediately; redirects recover 30-60% depending on topical relevance.',
    'Algorithm updates, seasonality and competitor moves are NOT modelled. Treat output as directional, not a guarantee.'
  ]
};

const llmContext = {
  scenarioName: b.scenarioName, horizonMonths: H,
  baselineClicks: responsePayload.baseline.clicks,
  predicted: responsePayload.predicted,
  breakdown: responsePayload.breakdown,
  verdict, riskScore, riskLevel, confidencePercent,
  topActions: actionRows.slice(0, 12).map(a => ({ label: a.label, expectedDelta: a.expectedDelta, flags: a.flags })),
  warnings: warnings.slice(0, 5)
};

return [{ json: { responsePayload, llmContext, requestActions: b.actions, requestStartedAt: b.requestStartedAt, tenantId: b.tenantId } }];

// Second validation boundary — on the LLM narrative. Never forward malformed model output.
const impact = $('Code - Predicted Impact').first().json;
const p = impact.responsePayload;
const resp = $input.first().json;

function fallback(reason) {
  const dir = p.predicted.deltaClicks >= 0 ? 'increase' : 'decrease';
  return {
    executiveSummary: `Projected ${dir} of ${Math.abs(p.predicted.deltaClicks)} monthly clicks (${p.predicted.deltaPercent === null ? 'n/a' : p.predicted.deltaPercent + '%'}) over ${p.horizonMonths} months. Risk: ${p.risk.level}. Confidence: ${p.confidencePercent}%.`,
    topRecommendations: [],
    sequencing: [],
    watchouts: [...new Set(p.risk.flags.map(f => f.code))].slice(0, 5),
    _fallbackReason: reason
  };
}

let n;
try {
  const raw = String(resp.text || resp.output || '{}').replace(/```json|```/g, '').trim();
  n = JSON.parse(raw);
} catch (e) { n = fallback('Failed to parse LLM JSON output.'); }

const isStrArr = v => Array.isArray(v) && v.every(x => typeof x === 'string');
const errors = [];
if (typeof n.executiveSummary !== 'string' || !n.executiveSummary.trim()) errors.push('executiveSummary invalid');
['topRecommendations', 'sequencing', 'watchouts'].forEach(k => { if (!isStrArr(n[k])) errors.push(k + ' invalid'); });
if (errors.length) n = fallback('LLM output failed schema validation: ' + errors.join('; '));

const narrative = {
  executiveSummary: n.executiveSummary.slice(0, 800),
  topRecommendations: n.topRecommendations.slice(0, 5),
  sequencing: n.sequencing.slice(0, 5),
  watchouts: n.watchouts.slice(0, 5),
  ...(n._fallbackReason ? { _fallbackReason: n._fallbackReason } : {})
};

const latencyMs = Date.now() - new Date(impact.requestStartedAt).getTime();
return [{
  json: {
    responsePayload: { ...p, narrative },
    log: {
      tenant_id: impact.tenantId, site_id: p.siteId, scenario_name: p.scenarioName,
      horizon_months: p.horizonMonths,
      actions: JSON.stringify(impact.requestActions),
      baseline_clicks: p.baseline.clicks,
      predicted_clicks: p.predicted.clicks, predicted_low: p.predicted.low, predicted_high: p.predicted.high,
      verdict: p.verdict, risk_score: p.risk.score, confidence_percent: p.confidencePercent,
      latency_ms: latencyMs,
      result: JSON.stringify(p),
      created_at: new Date().toISOString()
    }
  }
}];
